#include <bits/stdc++.h>
using namespace std;
int main(){ios::sync_with_stdio(false);cin.tie(nullptr);int n,m,q;if(!(cin>>n>>m>>q))return 0;int MW=(n+63)/64,QW=(q+63)/64;vector<vector<unsigned long long>>a(n,vector<unsigned long long>(MW)),rhs(n,vector<unsigned long long>(QW));for(int i=0;i<n;i++)a[i][i/64]|=1ULL<<(i%64);while(m--){int u,v;cin>>u>>v;--u;--v;a[u][v/64]|=1ULL<<(v%64);a[v][u/64]|=1ULL<<(u%64);}for(int z=0;z<q;z++)for(int i=0;i<n;i++){char c;cin>>c;if(c=='0')rhs[i][z/64]|=1ULL<<(z%64);}vector<int>pcol;int rank=0;for(int col=0;col<n;col++){int s=rank;while(s<n&&!(a[s][col/64]>>(col%64)&1))s++;if(s==n)continue;swap(a[s],a[rank]);swap(rhs[s],rhs[rank]);for(int i=rank+1;i<n;i++)if(a[i][col/64]>>(col%64)&1){for(int w=col/64;w<MW;w++)a[i][w]^=a[rank][w];for(int w=0;w<QW;w++)rhs[i][w]^=rhs[rank][w];}pcol.push_back(col);rank++;}vector<unsigned long long>bad(QW);for(int i=rank;i<n;i++)for(int w=0;w<QW;w++)bad[w]|=rhs[i][w];vector<vector<unsigned long long>>x(n,vector<unsigned long long>(QW));for(int r=rank-1;r>=0;r--){int col=pcol[r];x[col]=rhs[r];for(int w=col/64;w<MW;w++){unsigned long long z=a[r][w];if(w==col/64)z=(col%64==63?0:z&(~0ULL<<((col%64)+1)));while(z){int b=__builtin_ctzll(z),v=w*64+b;if(v<n)for(int j=0;j<QW;j++)x[col][j]^=x[v][j];z&=z-1;}}}for(int z=0;z<q;z++){if(bad[z/64]>>(z%64)&1){cout<<-1<<'\n';continue;}vector<int>ans;for(int i=0;i<n;i++)if(x[i][z/64]>>(z%64)&1)ans.push_back(i+1);cout<<ans.size();for(int v:ans)cout<<' '<<v;cout<<'\n';}}
